import { CanonicalFloat } from '@amc/canonical';
import {
  bookContext, markAsset, pageManifest, pageSpec,
  type AssetKind, type BookContext, type EvidenceRecord, type MarkAsset, type Mode, type PageManifest, type PageSpec, type PyValue,
} from '../src/index';
import raw from './fixtures/brandbook-parity.json';

// Generated by services/langgraph/tests/test_vnexus_brandbook_parity_fixture.py (Python is the reference).
export type Rec = { readonly [key: string]: unknown };
export const fixture = raw as unknown as Rec;

export const rec = (v: unknown): Rec => v as Rec;
export const list = (v: unknown): readonly unknown[] => v as readonly unknown[];
export const str = (v: unknown): string => v as string;

const NAMED: Readonly<Record<string, number>> = { nan: Number.NaN, inf: Infinity, '-inf': -Infinity };

/** `{"$float": "<repr>"}` -> CanonicalFloat; every other node is plain JSON. */
export function dec(node: unknown): PyValue {
  if (Array.isArray(node)) return node.map(dec);
  if (node === null || typeof node !== 'object') return node as PyValue;
  const entries = Object.entries(node);
  const [only] = entries;
  if (entries.length === 1 && only && only[0] === '$float') return new CanonicalFloat(NAMED[String(only[1])] ?? Number(only[1]));
  return Object.fromEntries(entries.map(([k, v]) => [k, dec(v)]));
}

/** A decoded float (tagged or plain) as a number. */
export function num(v: unknown): number {
  const d = dec(v);
  return d instanceof CanonicalFloat ? d.value : (d as number);
}

export function markFromSpec(m: Rec): MarkAsset {
  return markAsset({ kind: m['kind'] as AssetKind, sha256: m['sha256'] as string | null, svg: m['svg'] as string | null,
    source: str(m['source']), approved: m['approved'] as boolean });
}

export function manifestFromDump(dump: unknown): PageManifest {
  const d = rec(dump);
  return pageManifest(str(d['template_id']), str(d['template_version']), list(d['pages']).map((p) => pageSpec(p as PageSpec)));
}

export function contextFromSpec(specInput: unknown): BookContext {
  const spec = rec(specInput);
  return bookContext({
    brand_id: str(spec['brand_id']), brand_name: str(spec['brand_name']), genome_ref: str(spec['genome_ref']),
    resolution_hash: str(spec['resolution_hash']), approved: dec(spec['approved']) as Rec as { [k: string]: PyValue },
    sources: spec['sources'] as Record<string, string>, proposed: dec(spec['proposed']) as Rec as { [k: string]: PyValue },
    proposal_ref: spec['proposal_ref'] as string | null, evidence: spec['evidence'] as EvidenceRecord[], mode: spec['mode'] as Mode,
    locale: str(spec['locale']), mark: markFromSpec(rec(spec['mark'])),
    ...(spec['manifest'] === null ? {} : { manifest: manifestFromDump(spec['manifest']) }),
  });
}

/** A Python `outcome`: either `{ok}` or `{error: {type, message}}`. */
export function expectOutcome(run: () => unknown, outcome: unknown, label: string, same: (actual: unknown, expected: unknown) => void): void {
  const o = rec(outcome);
  if ('error' in o) {
    const err = rec(o['error']);
    let thrown: unknown;
    try {
      run();
    } catch (e) {
      thrown = e;
    }
    if (!(thrown instanceof Error)) throw new Error(`${label}: expected ${str(err['type'])}`);
    if (thrown.name !== err['type'] || thrown.message !== err['message']) {
      throw new Error(`${label}: got ${thrown.name}: ${thrown.message}, expected ${str(err['type'])}: ${str(err['message'])}`);
    }
    return;
  }
  same(run(), o['ok']);
}

export function specFields(fields: Rec): Map<string, PyValue> {
  return new Map(Object.entries(fields).map(([k, v]) => [k, dec(v)] as const));
}
